import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Asymmetric Storage","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/asymmetric-storage.md","filePath":"en/deep-dive/asymmetric-storage.md","lastUpdated":1788278373000}`),a={name:`deep-dive/asymmetric-storage.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="asymmetric-storage" tabindex="-1">Asymmetric Storage <a class="header-anchor" href="#asymmetric-storage" aria-label="Permalink to “Asymmetric Storage”">​</a></h1><p>Asymmetric storage means that the file structure at remote differs from real hierarchies at local. For example, the remote structure is flat, while the local files are nested inside folders.</p><h2 id="disadvantages-in-traditional-methods" tabindex="-1">Disadvantages in Traditional Methods <a class="header-anchor" href="#disadvantages-in-traditional-methods" aria-label="Permalink to “Disadvantages in Traditional Methods”">​</a></h2><p>Symmetric hierarchical file storage on both local and remote has significant drawbacks regarding query speed, request frequency, and obfuscation:</p><ul><li>during traversal, the APP needs to recursively traverse nested folders, the minimum time complexity is O(depth) when all folders of the same depth are traversed concurrently.</li><li>the APP needs to make network request for each folder, may reach rate limit.</li><li>during execution, the APP needs to care about folder hierarchies, the minimum time complexity is O(existing depth - target depth) with complex concurrency optimization.</li><li>the encrypted remote file structure mirrors the unencrypted shape, and files with the same basename always have the same ciphertext name, which signals insufficient obfuscation.</li></ul><p>Even classical asymmetric storage in <em>object storage</em> (flat entries, file path as keys) has drawbacks:</p><ul><li>when a file is deeply nested, the key becomes very long, may exceed max length (when encryption is applied, it can be longer)</li><li>the flat shape is decoupled from the real shape, making structural drift possible.</li><li>when a folder is renamed, all descendants need cascade renaming.</li></ul><p>Due to the reasons above, with respect to the fact that most users don&#39;t care about remote shape when syncing (they can disable if they&#39;d like to), <strong>Anchored Asymmetric Storage™</strong> is proposed to eliminate all the frictions. It provides O(1) remote traversal, O(1) remote operation, and full hierarchical semantics.</p><h2 id="mechanism" tabindex="-1">Mechanism <a class="header-anchor" href="#mechanism" aria-label="Permalink to “Mechanism”">​</a></h2><p>The files and folders are represented in a flat style at remote, no matter how nested is local.</p><p>Each folder has a generated 5-byte ASCII anchor prepended at the start of the folder basename with delimiter <code>~</code>. The root folder has ambient anchor <code>00000</code>.</p><p>Each file and folder also has the anchor of parent directory prepended at the start of the basename. So that the prepended basename become:</p><ul><li>file: <code>&lt;parent-anchor&gt;~&lt;basename&gt;</code></li><li>folder <code>&lt;parent-anchor&gt;&lt;local-anchor&gt;~&lt;basename&gt;</code></li><li>root: still <code>/</code></li></ul><p>All files and folders become literal files at remote side, the method to distinguish files and folders at remote is the presence of local anchor.</p><p>For example, a file tree like below:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ (root)</span></span>
<span class="line"><span>├── foo.md (file)</span></span>
<span class="line"><span>├── bar.md (file)</span></span>
<span class="line"><span>├── abc.md (file)</span></span>
<span class="line"><span>└── a-folder/ (folder)</span></span>
<span class="line"><span>    ├── nested.md (file)</span></span>
<span class="line"><span>    └── child.md (file)</span></span></code></pre></div><p>Can be flattened as:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ (root)</span></span>
<span class="line"><span>├── 00000~foo.md (file)</span></span>
<span class="line"><span>├── 00000~bar.md (file)</span></span>
<span class="line"><span>├── 00000~abc.md (file)</span></span>
<span class="line"><span>├── 00000z9E{m~a-folder (folder becomes empty file)</span></span>
<span class="line"><span>├── z9E{m~nested.md (file)</span></span>
<span class="line"><span>└── z9E{m~child.md (file)</span></span></code></pre></div><p>The anchor generation algorithm is deterministic, it needs to take <code>&lt;parent-anchor&gt;~&lt;basename&gt;</code> as seed to generate an anchor. For example, the seed of <code>a-folder/</code> into the algorithm is <code>00000~a-folder</code>.</p><p>Despite the determinism in generation algorithm, the implementation doesn&#39;t assume the anchor generation is deterministic. Since once it is, renaming a folder would require cascade rename of all descendants. Instead, the implementation should infer folder-anchor pairing from a list of existing, flattened file names.</p><h2 id="implementation" tabindex="-1">Implementation <a class="header-anchor" href="#implementation" aria-label="Permalink to “Implementation”">​</a></h2><p>Asymmetric storage is implemented as a <em>file system wrapper</em>. It depends on a direct adjacent <em>context wrapper</em> nearer to root to provide initial list of flattened file names to infer.</p><p>The wrapper maintains two symmetric maps of folder key to anchor and anchor to folder key, used by flattening and de-flattening. The two maps are built only once per sync lifecycle from the keys stored in <code>memoryDB</code> <code>remoteStatContext</code> store when the first non-root key needing flattening / de-flattening arrives.</p><p>Per-method specification:</p><ul><li><code>getUid()</code>: keep as-is.</li><li><code>read()</code>, <code>readStream()</code>, <code>write()</code>, <code>writeStream()</code>, <code>delete()</code>, <code>move()</code>, <code>stat()</code>, <code>exists()</code>, <code>mkdir()</code>, <code>list()</code>: flatten keys before delegating</li><li><code>move()</code>: special check before delegating: if the flattened old key and new key are the same, return directly.</li><li><code>stat()</code>, <code>list()</code>: de-flatten keys each item after return, flip <code>isDir</code> flag when local anchor detected.</li><li><code>mkdir()</code>: redirect to <code>write()</code> of an empty array buffer</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};